	T(5, "1e+06", "%g", 1000000.0);
	T(6, "0.0001", "%g", 0.0001);
	T(5, "1e-05", "%g", 0.00001);
	T(11, "1.23457e+08", "%g", 123456789.0);
	T(4, "3.14", "%.3g", 3.14159);
	T(3, "0.5", "%.0g", 0.5);
	T(3, "0.9", "%.1g", 0.95);
